const VERSION: &str = "main";
/// Expected `getVersion()` of the Level 0 ACL and of the base ACL.
const LEVEL0_VERSION: &str = "ACL v0.9.0";
const BASE_VERSION: &str = "ACL v0.7.0";
/// FHE type byte (index 30) of the test handle: 5 (`euint64`), as in the repo's `S3_CT_HANDLE`.
const HANDLE_FHE_TYPE: u8 = 5;
/// ERC-7201 location of `fhevm.storage.ACLRetirement` (ACL.sol `ACL_RETIREMENT_STORAGE_LOCATION`).
const RETIREMENT_LOCATION: B256 =
    b256!("e6ae1005b480da47ced1ed3eb5869a54ca87c5d592369277249f4148c0e86200");
/// Level 0 Core interface id (`retireAccount() ^ isAccountRetired(address)`).
const DAL_CORE_INTERFACE_ID: [u8; 4] = [0x55, 0x6d, 0x20, 0x88];
/// Latency loop sizes.
const N_FWD: usize = 10;
const N_V2_FWD: usize = 5;
const N_REJ: usize = 5;

alloy::sol! {
    /// TEST-ONLY view of the Level 0 additions to the ACL (absent from `fhevm_host_bindings`).
    #[sol(rpc)]
    interface IAclLevel0 {
        function retireAccount() external;
        function isAccountRetired(address account) external view returns (bool);
        function supportsInterface(bytes4 interfaceId) external view returns (bool);
        function retirementStorageLocation() external pure returns (bytes32);
    }

    /// TEST-ONLY: the dApp contract C retires itself (harness `DappStub.retireSelf`).
    #[sol(rpc)]
    interface IDappRetire {
        function retireSelf(address acl) external;
    }

    /// TEST-ONLY view of the Level 2 additions to the ACL (E1 Successor).
    #[sol(rpc)]
    interface IAclSuccession {
        function designateSuccessor(address successor) external;
        function acceptSuccession(address account) external;
        function confirmSuccessor() external;
        function resignSuccession(address account) external;
        function successorOf(address account) external view returns (address);
    }
}

